#!/usr/bin/env bash
# ONE definition of where the Linux build puts things, sourced by build.sh and publish_linux.sh.
# Requires $here (the deps/ directory) to be set by the caller.
#
# NOTHING generated by the Linux build may live inside the package tree. WSL compiles straight from
# the Windows checkout, so a staging dir under deps/ lands on DrvFs -- and its symlinks are reparse
# points that Windows cannot stat(). TestItemRunner walks the WHOLE package directory looking for
# @testitem, so one such symlink takes down the entire Windows test suite before a single test runs:
#
#   IOError: stat("...\deps\build_linux\libICE.so.6"): permission denied (EACCES)
#
# Staging in the WSL-native cache also drops the compile off DrvFs, which is much faster.
# Override the root with IGMT_LINUX_STAGE if the cache lives somewhere else.
igmt_stage_root=${IGMT_LINUX_STAGE:-${XDG_CACHE_HOME:-$HOME/.cache}/igmt}
igmt_cmake_dir=$igmt_stage_root/cmake
igmt_bundle_dir=$igmt_stage_root/build_linux
igmt_archive=$igmt_stage_root/iGMT-linux-x86_64-full.tar.gz

# One-time migration for a checkout built by the older scripts, which staged into deps/. These are
# pure build output and are about to be regenerated at the new location, so removing them costs
# nothing -- and leaving them would keep the Windows test suite broken.
igmt_drop_in_tree_build() {
    local legacy
    for legacy in $here/build_linux $here/.cmake_linux; do
        [[ -e $legacy ]] || continue
        printf '%s\n' Removing_in-tree_Linux_build_dir_that_breaks_Windows_tests:$legacy
        rm -rf -- $legacy
    done
}
